<script setup>
import {ref,onMounted,computed} from 'vue';import {api} from '../store';
const usuarios=ref([]),error=ref(''),aviso=ref(''),ocupado=ref(false),filtro=ref(''),form=ref({nombre:'',email:'',password:'',rol:'estudiante'}),cambio=ref(null),clave=ref('');
const visibles=computed(()=>usuarios.value.filter(u=>!filtro.value||u.rol===filtro.value));
async function cargar(){try{usuarios.value=await api('/usuarios')}catch(e){error.value=e.message}}
async function crear(){ocupado.value=true;error.value='';aviso.value='';try{await api('/usuarios','POST',form.value);form.value={nombre:'',email:'',password:'',rol:'estudiante'};aviso.value='Cuenta creada correctamente.';await cargar()}catch(e){error.value=e.message}finally{ocupado.value=false}}
async function restablecer(){try{error.value='';await api('/usuarios/'+cambio.value.id+'/password','PUT',{password:clave.value});cambio.value=null;clave.value='';aviso.value='Contraseña actualizada. Las sesiones anteriores se cerraron.'}catch(e){error.value=e.message}}
onMounted(cargar);
</script><template><div class="page-heading"><div><div class="eyebrow">ADMINISTRACIÓN</div><h2>Gestión de usuarios</h2><p>Crea cuentas académicas y asigna el perfil correspondiente.</p></div></div><div v-if="error" class="alert alert-danger">{{error}}</div><div v-if="aviso" class="alert alert-success">{{aviso}}</div><div class="row g-3 mb-4"><div class="col-md-6" v-for="r in ['docente','estudiante']" :key="r"><div class="card metric"><span>{{r==='docente'?'Docentes':'Estudiantes'}}</span><strong>{{usuarios.filter(u=>u.rol===r).length}}</strong></div></div></div><form class="card p-4 mb-4" @submit.prevent="crear"><h5>Nueva cuenta</h5><div class="row g-3"><label class="col-md-6">Nombre completo<input class="form-control" v-model.trim="form.nombre" required></label><label class="col-md-6">Correo<input class="form-control" type="email" v-model.trim="form.email" required></label><label class="col-md-6">Perfil<select class="form-select" v-model="form.rol"><option value="estudiante">Estudiante</option><option value="docente">Docente / tutor</option></select></label><label class="col-md-6">Contraseña inicial<input class="form-control" type="password" v-model="form.password" minlength="8" maxlength="128" required></label></div><div class="mt-3"><button class="btn btn-primary" :disabled="ocupado">Crear usuario</button></div></form><form v-if="cambio" class="card p-4 mb-4" @submit.prevent="restablecer"><h5>Restablecer contraseña de {{cambio.nombre}}</h5><label>Nueva contraseña<input class="form-control" type="password" v-model="clave" minlength="8" maxlength="128" required></label><div class="mt-3"><button class="btn btn-primary me-2">Guardar</button><button type="button" class="btn btn-outline-secondary" @click="cambio=null;clave=''">Cancelar</button></div></form><div class="card p-4"><div class="panel-heading"><h5>Usuarios registrados</h5><select class="form-select w-auto" v-model="filtro"><option value="">Todos</option><option value="docente">Docentes</option><option value="estudiante">Estudiantes</option></select></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Correo</th><th>Perfil</th><th>Acciones</th></tr></thead><tbody><tr v-for="u in visibles" :key="u.id"><td>{{u.nombre}}</td><td>{{u.email}}</td><td><span class="badge text-bg-light">{{u.rol}}</span></td><td><button class="btn btn-sm btn-outline-primary" @click="cambio=u;clave=''">Restablecer contraseña</button></td></tr></tbody></table></div><p v-if="!visibles.length" class="empty-state">No hay usuarios en esta categoría.</p></div></template>